@@ -1,30 +1,67 @@
 // Preserve every semantic object, material, geometry, animation and picking identity.
 // semanticId identifies an ordinary mesh; semanticIds identifies each instance.
 export function createWorld(THREE, scene) {
   const count = 1600;
-  const robots = [];
-  // Allocate geometry only once and share it among all robots
+  const columns = 40;
+  const rows = Math.floor(count / 40);
+
   const sharedGeometry = new THREE.BoxGeometry(.72, .48, .94);
-  // Only two material instances instead of 1600
   const orangeMaterial = new THREE.MeshStandardMaterial({color: 0xf59b52, roughness: .42, metalness: .35});
   const blueMaterial   = new THREE.MeshStandardMaterial({color: 0x4f8ca8, roughness: .42, metalness: .35});
+
+  const orangeIndices = [];
+  const blueIndices = [];
   for (let i = 0; i < count; i++) {
-    // Use shared material objects based on color
-    const material = i % 3 === 0 ? orangeMaterial : blueMaterial;
-    const mesh = new THREE.Mesh(sharedGeometry, material);
-    mesh.userData.semanticId = 'robot-' + i;
-    scene.add(mesh);
-    robots.push(mesh);
+    if (i % 3 === 0) {
+      orangeIndices.push(i);
+    } else {
+      blueIndices.push(i);
+    }
   }
+
+  const orangeMesh = new THREE.InstancedMesh(sharedGeometry, orangeMaterial, orangeIndices.length);
+  const blueMesh = new THREE.InstancedMesh(sharedGeometry, blueMaterial, blueIndices.length);
+
+  orangeMesh.userData.semanticIds = orangeIndices.map((i) => 'robot-' + i);
+  blueMesh.userData.semanticIds = blueIndices.map((i) => 'robot-' + i);
+
+  scene.add(orangeMesh);
+  scene.add(blueMesh);
+
+  const dummy = new THREE.Object3D();
+
   return {
     update(t) {
-      for (let i = 0; i < count; i++) {
+      for (let inst = 0; inst < orangeIndices.length; inst++) {
+        const i = orangeIndices[inst];
         const column = i % 40;
         const row = Math.floor(i / 40);
-        const position = new THREE.Vector3((column - 19.5) * 1.25, .32 + Math.sin(t * 1.8 + i * .13) * .04, (row - Math.floor(count / 40) / 2) * 1.3 + Math.sin(t * .4 + column * .2) * .4);
-        robots[i].position.copy(position);
-        robots[i].rotation.y = Math.sin(t * .5 + i * .04) * .18;
+        dummy.position.set(
+          (column - 19.5) * 1.25,
+          .32 + Math.sin(t * 1.8 + i * .13) * .04,
+          (row - Math.floor(count / 40) / 2) * 1.3 + Math.sin(t * .4 + column * .2) * .4
+        );
+        dummy.rotation.set(0, Math.sin(t * .5 + i * .04) * .18, 0);
+        dummy.updateMatrix();
+        orangeMesh.setMatrixAt(inst, dummy.matrix);
       }
+
+      for (let inst = 0; inst < blueIndices.length; inst++) {
+        const i = blueIndices[inst];
+        const column = i % 40;
+        const row = Math.floor(i / 40);
+        dummy.position.set(
+          (column - 19.5) * 1.25,
+          .32 + Math.sin(t * 1.8 + i * .13) * .04,
+          (row - Math.floor(count / 40) / 2) * 1.3 + Math.sin(t * .4 + column * .2) * .4
+        );
+        dummy.rotation.set(0, Math.sin(t * .5 + i * .04) * .18, 0);
+        dummy.updateMatrix();
+        blueMesh.setMatrixAt(inst, dummy.matrix);
+      }
+
+      orangeMesh.instanceMatrix.needsUpdate = true;
+      blueMesh.instanceMatrix.needsUpdate = true;
     }
   };
 }
